operations.search:
const measuredCost =
  Number(
    measured?.cost
  );

if (
  Number.isFinite(
    measuredCost
  )
) {
  return measuredCost;
}

operations.replace:
const measuredCost =
  typeof measured?.cost === "number"
    ? measured.cost
    : NaN;

if (
  Number.isFinite(
    measuredCost
  )
) {
  return measuredCost;
}
